const {chromium} = require(process.env.FLEET_PLAYWRIGHT_MODULE);
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const [origin, viewport] = process.argv.slice(2);
(async () => {
  const browser = await chromium.launch({channel: process.env.FLEET_BROWSER_CHANNEL || 'chrome', headless: true});
  try {
    const context = await browser.newContext({viewport: viewport === 'mobile' ? {width:390,height:844} : {width:1440,height:1100}});
    const login = await context.request.post(origin + '/api/accounts/login', {data:{email:'admin@example.test', password:'safe-password-123!'},headers:{Origin:origin}});
    assert.equal(login.status(),200);
    const page = await context.newPage(); page.setDefaultTimeout(12000);
    const errors = []; page.on('pageerror', e => errors.push(e.message));
    await page.goto(origin + '/assistant');
    await page.getByText('请先配置可用模型和工作区', {exact:true}).waitFor();
    if (viewport === 'mobile') await page.getByRole('button',{name:'打开导航',exact:true}).click();
    await page.locator('[data-nav="settings"]').click();
    assert.equal(await page.locator('.settings-page').evaluate(node => getComputedStyle(node).display), viewport === 'mobile' ? 'flex' : 'grid');
    await page.getByRole('button',{name:'新增模型源',exact:true}).click();
    await page.getByLabel('模型配置 ID',{exact:true}).fill('browser-model');
    await page.getByLabel('模型名称',{exact:true}).fill('browser-gpt');
    await page.getByLabel('API URL',{exact:true}).fill('https://models.example.test/v1');
    await page.getByLabel('API Key',{exact:true}).fill('private-browser-key');
    await page.getByRole('button',{name:'保存配置',exact:true}).click();
    await page.getByText('配置已保存，将用于之后的新任务',{exact:true}).waitFor();
    await page.reload();
    await page.getByRole('button',{name:/browser-gpt/}).click();
    assert.equal(await page.getByLabel('API URL',{exact:true}).inputValue(),'https://models.example.test/v1');
    assert.equal(await page.getByLabel('API Key',{exact:true}).inputValue(),'');
    await page.getByLabel('API URL',{exact:true}).fill('https://new.example.test/v1');
    await page.getByRole('button',{name:'保存配置',exact:true}).click();
    await page.getByText('配置已保存，将用于之后的新任务',{exact:true}).waitFor();
    await page.getByRole('button',{name:/browser-gpt/}).click();
    const snapshot = await (await context.request.get(origin + '/api/platform/v1/settings')).json();
    const row = snapshot.models[0];
    assert.equal(row.secret_configured,true);
    const outside = await context.request.put(origin + '/api/platform/v1/settings/models/browser-model', {headers:{Origin:origin},data:{expected_digest:row.digest,value:{provider:row.provider,model:'external-update',provider_config:row.provider_config,enabled:true,capabilities:{}}}});
    assert.equal(outside.status(),200);
    await page.getByLabel('模型名称',{exact:true}).fill('stale-model');
    await page.getByRole('button',{name:'保存配置',exact:true}).click();
    await page.getByText(/配置已更改，请重新加载后保存/).waitFor();
    const nav = page.getByRole('navigation',{name:'设置分类',exact:true});
    await nav.getByRole('link',{name:'VM 与执行节点',exact:true}).click();
    await page.getByRole('button',{name:'新增执行节点',exact:true}).click();
    await page.getByLabel('节点 ID',{exact:true}).fill('browser-node');
    await page.getByLabel('节点名称',{exact:true}).fill('测试 VM');
    await page.getByLabel('能力声明（JSON）',{exact:true}).fill('{"workspace.exec":true}');
    await page.getByRole('button',{name:'保存配置',exact:true}).click();
    await page.getByText('配置已保存，将用于之后的新任务',{exact:true}).waitFor();
    await nav.getByRole('link',{name:'工作区与存储',exact:true}).click();
    await page.getByRole('button',{name:'新增工作区',exact:true}).click();
    await page.getByLabel('工作区 ID',{exact:true}).fill('browser-workspace');
    await page.getByLabel('工作区名称',{exact:true}).fill('测试目录');
    await page.getByLabel('工作目录绝对路径',{exact:true}).fill('/srv/browser-workspace');
    await page.getByLabel('默认执行节点',{exact:true}).selectOption('browser-node');
    await page.getByRole('button',{name:'保存配置',exact:true}).click();
    await page.getByText('配置已保存，将用于之后的新任务',{exact:true}).waitFor();
    await nav.getByRole('link',{name:'默认配置',exact:true}).click();
    await page.getByLabel('默认模型',{exact:true}).selectOption('browser-model');
    await page.getByLabel('默认工作区',{exact:true}).selectOption('browser-workspace');
    await page.getByRole('button',{name:'保存默认配置',exact:true}).click();
    await page.getByText('默认配置已保存',{exact:true}).waitFor();
    if (viewport === 'mobile') await page.getByRole('button',{name:'打开导航',exact:true}).click();
    await page.locator('[data-nav="assistant"]').click();
    await page.getByLabel('模型', {exact:true}).locator('option[value="browser-model"]').waitFor({state:'attached'});
    assert.equal(await page.getByLabel('模型', {exact:true}).inputValue(),'browser-model');
    assert.equal(await page.getByLabel('工作区', {exact:true}).inputValue(),'browser-workspace');
    await page.evaluate(() => window.dispatchEvent(new CustomEvent('fleet:navigate',{detail:{path:'/settings/runtime'}})));
    await page.getByLabel('记忆管理',{exact:true}).check();
    await page.getByRole('button',{name:'保存服务器配置',exact:true}).click();
    await page.getByText(/已保存。需要重启 Hub 后生效/).waitFor();
    await page.reload();
    assert.equal(await page.getByLabel('记忆管理',{exact:true}).isChecked(),true);
    await page.getByLabel('搜索设置',{exact:true}).fill('VM');
    assert.equal(await nav.getByRole('link',{name:'VM 与执行节点',exact:true}).isVisible(),true);
    assert.equal(await nav.getByRole('link',{name:'模型源与 API',exact:true}).isVisible(),false);
    await page.getByLabel('搜索设置',{exact:true}).fill('');
    await nav.getByRole('link',{name:'账号与访问',exact:true}).click();
    await page.getByRole('heading',{name:'个人资料',exact:true}).waitFor();
    assert.equal(await page.getByRole('region',{name:'MCP 集成管理',exact:true}).count(),0);
    await nav.getByRole('link',{name:'模型源与 API',exact:true}).click();
    // The cached form retains local edits; explicit reload reconciles the conflict.
    await page.reload();
    await page.getByRole('button',{name:/external-update/}).click();
    assert.equal(await page.getByLabel('API Key',{exact:true}).inputValue(),'');
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth),true);
    if(process.env.FLEET_SCREENSHOTS) {
      await fs.mkdir(process.env.FLEET_SCREENSHOTS,{recursive:true});
      await page.evaluate(() => scrollTo(0,0));
      await page.screenshot({path:path.join(process.env.FLEET_SCREENSHOTS,'settings-'+viewport+'.png'),fullPage:true});
    }
    await context.clearCookies();
    await page.goto(origin + '/settings/workspaces');
    await page.waitForURL('**/login?**');
    assert.equal(new URL(page.url()).searchParams.get('return_to'), '/settings/workspaces');
    await page.getByLabel('账号或邮箱',{exact:true}).fill('admin@example.test');
    await page.getByLabel('密码',{exact:true}).fill('safe-password-123!');
    await page.getByRole('button',{name:'登录',exact:true}).click();
    await page.waitForURL('**/settings/workspaces');
    await page.getByRole('heading',{name:'工作区与存储',exact:true}).waitFor();
    assert.deepEqual(errors,[]);
    console.log(JSON.stringify({viewport,saveReload:true,conflict:true,defaultWorkspace:true,runtime:true,pageErrors:errors}));
  } finally {await browser.close();}
})().catch(e=>{console.error(e);process.exit(1);});
